   "sez": "ambiente",
   "titolo": "Il cambiamento climatico minaccia la rara tundra dei monti Krkonoše",
   "orig": "Climate change threatens rare Krkonoše mountain tundra",
   "lead": "La tundra artica dei monti Krkonoše, nella Repubblica Ceca settentrionale, sta progressivamente scomparendo a causa dell'aumento delle temperature, che permette ad arbusti, erbe alte e cespugli nani di espandersi sulle creste montuose. L'amministrazione del Parco nazionale dei Krkonoše sta cercando modi per proteggere le rare piante adattate al freddo rispettando al contempo i processi naturali in una delle riserve naturali più preziose e protette del Paese. Lo riferisce Radio Prague International.",
   "more": [
    "I monti Krkonoše ospitano un ecosistema unico simile alla tundra artica, sopravvissuto dall'ultima era glaciale su creste di alta quota. Si tratta di uno degli habitat più rari e fragili d'Europa centrale, rifugio di specie vegetali che non si trovano altrove nella regione."
   ],
