   "id": "z3123595d",
   "sez": "mondo",
   "titolo": "Si lancia dalla nave da crociera e sopravvive 20 ore in mare aperto",
   "orig": "“Si è lanciata giù dalla nave perché voleva sbarcare”: passeggera cade dalla nave da crociera e sopravvive per oltre 20 ore in mare aperto: l’incredibile salvataggio grazie alla luce del salvagente",
   "lead": "Una passeggera salvadoregna di 44 anni si è gettata in mare venerdì mattina dalla nave da crociera Odyssey of the Seas, in navigazione al largo delle coste greche, perché voleva sbarcare. La donna è sopravvissuta per oltre 20 ore alla deriva nelle acque del Mediterraneo, prima di essere salvata grazie alla piccola luce intermittente del suo salvagente, individuata durante un'operazione di soccorso notturna. Lo riferisce Il Fatto Quotidiano.",
   "more": [
    "Le navi da crociera moderne solcano rotte internazionali trasportando migliaia di passeggeri; le cadute in mare, seppur rare, rappresentano emergenze complesse per i soccorsi data l'estensione delle acque da perlustrare e le condizioni spesso notturne delle ricerche."
   ],
