   "sez": "tech",
   "titolo": "Google rende pubblico Gemini 4 Argon, puntando sulla sicurezza contro usi malevoli",
   "orig": "Gemini 4 Argon, ecco come Google lo ha reso sicuro contro gli usi malevoli",
   "lead": "Google ha messo a disposizione del pubblico il nuovo modello di intelligenza artificiale Gemini 4 Argon, integrato nell'app Gemini e collegato a oltre 40 servizi. Il sistema può continuare a eseguire compiti anche dopo che l'utente ha chiuso l'applicazione. L'azienda ha illustrato le misure adottate per renderlo più sicuro rispetto ai rischi biologici e informatici legati a un possibile uso malevolo del modello.",
   "more": [
    "Gemini è la famiglia di modelli di intelligenza artificiale sviluppata da Google, concorrente di sistemi come GPT. I modelli più avanzati vengono sottoposti a test di sicurezza per limitare rischi legati a un uso improprio, ad esempio nella creazione di contenuti pericolosi o nella manipolazione di sistemi informatici."
   ],
