   "lead": "Phoebe Bridgers è tornata a esibirsi insieme a Julien Baker e Lucy Dacus, le sue compagne nel progetto Boygenius, per una sessione acustica diretta dal regista Lance Oppenheim al Cherry Lane Theatre di New York. Il video fa parte della serie 'Sound Check At Cherry Lane Theatre', prodotta da A24, che mette in dialogo musicisti e cineasti attraverso brevi performance in un contesto intimo. Lo riferisce OndaRock.",
