   "titolo": "Proxima Centauri, la stella più vicina al nostro Sole",
   "orig": "Proxima Centauri is the closest star to our sun",
   "lead": "Proxima Centauri è la stella più vicina al Sole, a una distanza di 4,22 anni luce. Ospita almeno tre pianeti conosciuti ed è caratterizzata da violente eruzioni solari. Lo riferisce EarthSky.",
   "more": [
    "Proxima Centauri è una nana rossa che fa parte del sistema stellare Alpha Centauri, il più vicino al nostro Sistema Solare. Tra i pianeti scoperti attorno a essa vi è Proxima b, situato nella zona abitabile della stella, oggetto di grande interesse scientifico."
   ],
