   "orig": "(LEAD) Defense chief visits Gwangju air base amid planned relocation for chip project",
   "lead": "Il ministro della Difesa sudcoreano Kang Shin-chul ha visitato una base aerea a Gwangju nell'ambito di un progetto di trasferimento legato a un piano di sviluppo dei semiconduttori. La visita si inserisce in un più ampio programma di rilocalizzazione pianificata connesso al progetto sui chip. Lo riferisce Yonhap.",
