   "orig": "Trailblazing technique uncovers real shape of scorching-hot exoplanet atmospheres",
   "lead": "Una nuova tecnica di ricerca ha permesso di individuare la forma reale delle atmosfere di esopianeti rovente, rivelando che non sono sfere perfette come finora rappresentate, ma sfere deformate. Lo studio segna un cambiamento nel modo in cui gli scienziati immaginano questi mondi alieni incandescenti, finora raffigurati come corpi circolari. Lo riferisce Phys.org.",
