   "orig": "FIFPRO report highlights growing pains in women's football",
   "lead": "Un rapporto di FIFPRO evidenzia la crescita del calcio femminile a livello mondiale, con ricavi attesi superiori a un miliardo di dollari e nuove nazionali protagoniste ai Mondiali Under 17. Il documento segnala però anche la necessità di una maggiore struttura organizzativa a livello globale per sostenere questa espansione. Lo riferisce Deutsche Welle.",
