   "lead": "Anthropic ha aperto un ufficio a Singapore e firmato un accordo con il governo della città-stato in materia di sicurezza dell'intelligenza artificiale. L'accordo riguarda la sicurezza dell'IA, la valutazione dei modelli, l'adozione responsabile della tecnologia e la gestione degli incidenti legati al suo utilizzo. Lo riferisce CNA.",
