   "orig": "BFF Academy marks milestone with first Cambridge Checkpoint examination",
   "lead": "La BFF Academy del Bhutan ha raggiunto un traguardo importante facendo sostenere ai suoi studenti di classe VIII il primo esame Cambridge Lower Secondary Checkpoint. L'accademia, fondata nel 2022, combina da sempre l'apprendimento scolastico con l'allenamento calcistico, e introduce ora questo nuovo percorso accademico per i propri studenti. Lo riferisce Bhutan Broadcasting Service.",
