   "lead": "Un'opinione pubblicata su STAT da Joel Dodge sostiene che gli stati americani possano fungere da 'ultima linea di difesa' contro la politica anti-vaccinale dell'amministrazione Trump, in un contesto di possibili carenze di vaccini a livello federale. Lo riferisce STAT.",
