   "titolo": "Tsui Hark al Lumière Festival: «Non sappiamo dove ci porterà il futuro»",
   "orig": "Tsui Hark at Lumière Festival: ‘We don't know where the future will bring us’",
   "lead": "Il celebre regista di Hong Kong Tsui Hark ha incontrato Euronews Culture durante il Lumière Film Festival di Lione, parlando del rapporto tra cinema, tecnologia e timori legati al futuro. Il regista ha osservato che una caratteristica comune dell'umanità è la paura di essere sostituiti da qualcosa di nuovo, riflessione che ha applicato al dibattito attuale sull'evoluzione del cinema e delle tecnologie che lo accompagnano. L'intervista si è svolta nell'ambito del festival che celebra la storia e il futuro del cinema. Lo riferisce Euronews.",
   "more": [
    "Tsui Hark è uno dei più influenti cineasti di Hong Kong, noto per aver contribuito a rinnovare il cinema d'azione e fantastico asiatico dagli anni Ottanta. Il Lumière Festival di Lione è una delle principali rassegne europee dedicate alla storia del cinema."
   ],
