   "sez": "salute",
   "titolo": "Opinione: il microbioma intestinale dei neonati potrebbe essere la chiave per la salute del cervello",
   "orig": "Opinion: We think a baby’s gut microbiome could be key to lifelong brain health",
   "lead": "In un articolo di opinione pubblicato da STAT, Holly Baines e George Vradenburg sostengono che il microbioma intestinale dei neonati potrebbe giocare un ruolo centrale nella salute cerebrale a lungo termine. Gli autori chiedono una ricerca più rigorosa e su larga scala per comprendere meglio il cosiddetto asse intestino-cervello nel corso di tutta la vita, partendo proprio dalle fasi più precoci dello sviluppo. La proposta nasce dalla convinzione che investire nello studio di questo legame biologico possa avere ricadute importanti sulla prevenzione di malattie neurologiche. Lo riferisce STAT.",
   "more": [
    "L'asse intestino-cervello è il sistema di comunicazione bidirezionale tra il microbioma intestinale e il sistema nervoso centrale, oggetto crescente di studi scientifici per il suo possibile ruolo in patologie neurologiche, psichiatriche e dello sviluppo."
   ],
