   "sez": "mondo",
   "titolo": "La Colombia apre un'ambasciata a Gerusalemme e ripristina l'accordo di libero scambio con Israele",
   "orig": "Colombia opens embassy in Jerusalem, restores free trade deal with Israel",
   "lead": "La Colombia ha inaugurato mercoledì la propria ambasciata a Gerusalemme, diventando il decimo paese a farlo. La decisione arriva dal nuovo presidente colombiano Abelardo de la Espriella, che ha così ribaltato la rottura diplomatica con Israele voluta dal suo predecessore, ripristinando anche l'accordo di libero scambio tra i due paesi. Il ministro degli Esteri israeliano ha definito la giornata importante sia per lo Stato di Israele sia per la città di Gerusalemme. L'apertura segna un cambiamento netto nella politica estera colombiana verso Israele. Lo riferisce The Straits Times, ripreso anche da Middle East Eye.",
   "more": [
    "Il trasferimento di ambasciate a Gerusalemme è una questione politicamente sensibile, perché la maggior parte della comunità internazionale non riconosce la città come capitale di Israele a causa delle rivendicazioni palestinesi su Gerusalemme Est. Pochi paesi hanno finora compiuto questo passo."
   ],
