   "titolo": "Carichi di lavoro più sicuri per gli infermieri potrebbero alleviare l'affollamento dei pronto soccorso",
   "orig": "Safer nurse workloads could alleviate emergency department crowding",
   "lead": "Un nuovo studio condotto dai ricercatori del Center for Health Outcomes and Policy Research (CHOPR) della Penn Nursing ha rilevato che migliorare i carichi di lavoro degli infermieri negli ospedali potrebbe ridurre i ritardi nelle cure che contribuiscono al sovraffollamento dei pronto soccorso. La ricerca suggerisce un legame diretto tra condizioni di lavoro più sostenibili per il personale infermieristico e una gestione più efficiente dei pazienti in arrivo nei reparti di emergenza. Lo studio punta l'attenzione su un problema diffuso nei sistemi sanitari ospedalieri. Lo riferisce Medical Xpress.",
   "more": [
    "Il sovraffollamento dei pronto soccorso è un problema cronico in molti sistemi sanitari, spesso legato alla carenza di personale e letti disponibili, con conseguenze su tempi di attesa e qualità delle cure fornite ai pazienti."
   ],
